// static
bool UnionTraits<::brave_rewards::mojom::DBValue::DataView, ::brave_rewards::mojom::DBValuePtr>::Read(
    ::brave_rewards::mojom::DBValue::DataView input,
    ::brave_rewards::mojom::DBValuePtr* output) {
  using UnionType = ::brave_rewards::mojom::DBValue;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kIntValue: {
      *output = UnionType::NewIntValue(input.int_value());
      break;
    }
    case Tag::kInt64Value: {
      *output = UnionType::NewInt64Value(input.int64_value());
      break;
    }
    case Tag::kDoubleValue: {
      *output = UnionType::NewDoubleValue(input.double_value());
      break;
    }
    case Tag::kBoolValue: {
      *output = UnionType::NewBoolValue(input.bool_value());
      break;
    }
    case Tag::kStringValue: {
      std::string result_string_value{};
      if (!input.ReadStringValue(&result_string_value))
        return false;

      *output = UnionType::NewStringValue(
          std::move(result_string_value));
      break;
    }
    case Tag::kNullValue: {
      *output = UnionType::NewNullValue(input.null_value());
      break;
    }
    default:

      return false;
  }
  return true;
}

// static
bool UnionTraits<::brave_rewards::mojom::DBCommandResult::DataView, ::brave_rewards::mojom::DBCommandResultPtr>::Read(
    ::brave_rewards::mojom::DBCommandResult::DataView input,
    ::brave_rewards::mojom::DBCommandResultPtr* output) {
  using UnionType = ::brave_rewards::mojom::DBCommandResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kRecords: {
      std::vector<::brave_rewards::mojom::DBRecordPtr> result_records{};
      if (!input.ReadRecords(&result_records))
        return false;

      *output = UnionType::NewRecords(
          std::move(result_records));
      break;
    }
    case Tag::kValue: {
      ::brave_rewards::mojom::DBValuePtr result_value{};
      if (!input.ReadValue(&result_value))
        return false;

      *output = UnionType::NewValue(
          std::move(result_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

