void RewardsDatabaseAsyncWaiter::RunDBTransaction(
    DBTransactionPtr transaction, DBCommandResponsePtr* out_response) {
  base::RunLoop loop;
  proxy_->RunDBTransaction(
      std::move(transaction),
      base::BindOnce(
          [](base::RunLoop* loop,
             DBCommandResponsePtr* out_response
,
             DBCommandResponsePtr response) {*out_response = std::move(response);
            loop->Quit();
          },
          &loop,
          out_response));
  loop.Run();
}

